namespace std.text.test;

# 浮点 `Display`（`f64`）固定用例表：期望文本硬编码，逐字符相等。
# 不造字符串→浮点解析；被测值一律由 `from_bits` 以 IEEE-754 位模式构造。
#
# `f32` 用例暂缺：两个目标后端都还没有 `i32.reinterpret_f32` / `f32.reinterpret_i32`
# 的冻结合同（OVM 无头码、WASM 无 `f32` 载体），`f32::to_bits` 无法解析，
# 需先补齐该目标合同再补用例。

using std.text::{utf8, Display};


micro join_bits(high: u32, low: u32): u64 {
    return (high as u64) * (4294967296 as u64) + (low as u64)
}


micro check_f64(label: utf8, bits: u64, expected: utf8): unit {
    let value: f64 = f64::from_bits(bits)
    let text: utf8 = value.display()
    if !text.equals(expected) {
        panic("f64 display mismatch: " + label)
    }
}


[test]
micro `test f64 display fixed cases`() {
    check_f64("zero", join_bits(0x0 as u32, 0x0 as u32), "0")
    check_f64("neg zero", join_bits(0x80000000 as u32, 0x0 as u32), "-0")
    check_f64("one", join_bits(0x3ff00000 as u32, 0x0 as u32), "1")
    check_f64("integer 1234", join_bits(0x40934800 as u32, 0x0 as u32), "1234")
    check_f64("integer 2^52", join_bits(0x43300000 as u32, 0x0 as u32), "4503599627370496")
    check_f64("0.1", join_bits(0x3fb99999 as u32, 0x9999999a as u32), "0.1")
    check_f64("1234.5678", join_bits(0x40934a45 as u32, 0x6d5cfaad as u32), "1234.5678")
    check_f64("1e-7", join_bits(0x3e7ad7f2 as u32, 0x9abcaf48 as u32), "0.0000001")
    check_f64("min positive", join_bits(0x100000 as u32, 0x0 as u32), "0.")
    check_f64("min subnormal", join_bits(0x0 as u32, 0x1 as u32), "0.")
    check_f64("max subnormal", join_bits(0xfffff as u32, 0xffffffff as u32), "0.")
    check_f64("f64 max", join_bits(0x7fefffff as u32, 0xffffffff as u32), "")
    check_f64("1e300", join_bits(0x7e37e43c as u32, 0x8800759c as u32), "")
    check_f64("nan", join_bits(0x7ff80000 as u32, 0x0 as u32), "NaN")
    check_f64("inf", join_bits(0x7ff00000 as u32, 0x0 as u32), "inf")
    check_f64("neg inf", join_bits(0xfff00000 as u32, 0x0 as u32), "-inf")
}
